#include "gba/genres/AutoBattlerModule.h"
#include "gba/genres/GenreUtil.h"
#include <algorithm>
#include <cmath>
#include <sstream>

namespace gba { using namespace genreutil;
std::string AutoBattlerModule::genre()const{return "auto_battler";}
std::vector<ParameterSpec>AutoBattlerModule::balanceParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&u:arrayObjects(g.raw,"units")){auto id=str(u,"id");p.push_back(spec("unit."+id+".costMul",1,.5,2,.16));p.push_back(spec("unit."+id+".powerMul",1,.45,2.5,.18));p.push_back(spec("unit."+id+".traitMul",1,.5,2.5,.18));p.push_back(spec("unit."+id+".shopMul",1,.5,1.8,.15));}p.push_back(spec("enemyScale",1,.6,1.8,.15));p.push_back(spec("economyMul",1,.65,1.6,.14));return p;}
std::vector<ParameterSpec>AutoBattlerModule::strategyParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&u:arrayObjects(g.raw,"units"))p.push_back(spec("pref."+str(u,"id"),1,.02,4,.22));p.push_back(spec("reroll",.5,0,1.5,.18));p.push_back(spec("econ",.8,.1,2,.18));p.push_back(spec("traitBias",1,.1,2.5,.2));return p;}
SimulationResult AutoBattlerModule::simulate(const GameDefinition&g,const Genome&b,const Genome&s,std::uint64_t seed,int maxP)const{std::mt19937_64 rng(seed);SimulationResult r;r.strategyId=s.id;r.balanceId=b.id;r.seed=seed;auto units=arrayObjects(g.raw,"units");auto rules=g.raw["rules"];double hp=attr(rules,"playerHp",100),startHp=hp,gold=attr(rules,"startGold",10),income=gold;std::map<std::string,double>owned;double early=hp;int boardMax=static_cast<int>(attr(rules,"boardSize",8));for(int round=1;round<=maxP;++round){double inc=(attr(rules,"income",5)+std::min(5.0,std::floor(gold/10)))*gene(b,"economyMul");gold+=inc;income+=inc;int shops=1+(s.get("reroll",.5)>.8?1:0);for(int sh=0;sh<shops;++sh){const Json*best=nullptr;double bu=-1,bc=0;for(const auto&u:units){auto id=str(u,"id"),trait=str(u,"trait","none");double cost=attr(u,"cost",2)*gene(b,"unit."+id+".costMul");if(cost>gold)continue;double traitCount=0;for(const auto&v:units)if(str(v,"trait","none")==trait)traitCount+=owned[str(v,"id")];double util=s.get("pref."+id,1)*(1+s.get("traitBias",1)*std::min(1.0,traitCount/4.0))*gene(b,"unit."+id+".shopMul")*attr(u,"power",5)/std::max(.5,cost)*(.85+.3*rand01(rng));if(util>bu){bu=util;best=&u;bc=cost;}}if(best){auto id=str(*best,"id");gold-=bc;owned[id]++;r.usage[id]++;}}
 double power=0;std::map<std::string,double>traitCounts;for(const auto&u:units)traitCounts[str(u,"trait","none")]+=owned[str(u,"id")];int usedSlots=0;for(const auto&u:units){auto id=str(u,"id"),trait=str(u,"trait","none");double n=owned[id];if(n<=0)continue;double board=std::min(n,static_cast<double>(std::max(0,boardMax-usedSlots)));usedSlots+=static_cast<int>(board);double stars=1+std::floor(n/3);double traitBonus=1+std::min(.8,traitCounts[trait]*.08*gene(b,"unit."+id+".traitMul"));double c=board*attr(u,"power",5)*gene(b,"unit."+id+".powerMul")*(1+.45*(stars-1))*traitBonus;power+=c;r.contribution[id]+=c;if(usedSlots>=boardMax)break;}
 double enemy=(attr(rules,"enemyPowerBase",18)+round*attr(rules,"enemyGrowth",3.0))*gene(b,"enemyScale")*(.9+.2*rand01(rng));double ratio=power/std::max(1.0,enemy);if(ratio<1)hp-=std::ceil((1-ratio)*(4+round*.35));else gold+=1; if(round==5)early=hp;r.progress=round;if(hp<=0){r.success=false;break;}}
r.success=r.progress>=maxP;r.earlySafety=clamp01(early/startHp);r.resourceIncome=std::max(1.0,income);r.resourceResidual=gold;r.score=r.progress*30+r.earlySafety*450+r.success*1000;return r;}
EvaluationSummary AutoBattlerModule::evaluateBalance(const GameDefinition&g,const Genome&b,const std::vector<SimulationResult>&runs)const{auto e=IGameModule::evaluateBalance(g,b,runs);e.fitness-=std::max(0.0,e.topShare-.42)*5000;e.fitness-=std::max(0.0,e.topPairShare-.68)*6500;e.fitness+=e.diversity*850;std::ostringstream o;o<<"AutoBattler target="<<e.fitness<<" round="<<e.avgProgress<<" top="<<e.topShare;e.explanation=o.str();return e;}
std::vector<Genome>AutoBattlerModule::targetedBalanceExperiments(const GameDefinition&g,const Genome&base,const EvaluationSummary&c,std::uint64_t&nid,int gen,std::mt19937_64&,double strength)const{std::vector<Genome>v;std::string hi,lo;double a=-1,z=1e99;for(const auto&u:arrayObjects(g.raw,"units")){auto id=str(u,"id");double q=c.meanContribution.count(id)?c.meanContribution.at(id):0,x=c.meanUsage.count(id)?c.meanUsage.at(id):0;if(q>a){a=q;hi=id;}if(x<z){z=x;lo=id;}}if(!hi.empty()&&!lo.empty()&&hi!=lo){Genome n=base;n.id=nid++;n.generation=gen;n.note="anti-comp-meta:"+hi+"->"+lo;n.genes["unit."+hi+".powerMul"]*=1-strength*.28;n.genes["unit."+lo+".powerMul"]*=1+strength*.28;n.genes["unit."+lo+".shopMul"]*=1+strength*.15;v.push_back(n);}return v;}
}
